create extension if not exists pgcrypto;
create table if not exists public.testimonies (id uuid primary key default gen_random_uuid(),full_name text not null check(char_length(full_name) between 2 and 120),email text,language text not null default 'en',country text,parish text,event_date date,healing_type text,testimony_text text not null check(char_length(testimony_text) between 60 and 7000),contact_permission boolean not null default false,consent_publish boolean not null default false,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now(),published_at timestamptz,moderated_at timestamptz,moderated_by uuid references auth.users(id),moderation_note text);
create table if not exists public.testimony_rate_limits (ip_hash text primary key,window_start timestamptz not null default now(),attempts integer not null default 0);
create table if not exists public.testimony_settings (singleton boolean primary key default true check(singleton),intake_enabled boolean not null default false);
insert into public.testimony_settings(singleton,intake_enabled) values(true,false) on conflict(singleton) do nothing;
alter table public.testimonies enable row level security; alter table public.testimony_rate_limits enable row level security; alter table public.testimony_settings enable row level security;
revoke all on public.testimonies from anon; revoke all on public.testimony_rate_limits from anon,authenticated; revoke all on public.testimony_settings from anon,authenticated;
create policy "public reads approved only" on public.testimonies for select to anon using(status='approved' and published_at is not null);
create policy "moderators manage testimonies" on public.testimonies for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='moderator') with check((auth.jwt()->'app_metadata'->>'role')='moderator');
create or replace function public.accept_testimony(p_ip_hash text,p_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; v_setting boolean; v_limit testimony_rate_limits%rowtype; begin select intake_enabled into v_setting from testimony_settings where singleton=true; if coalesce(v_setting,false)=false then raise exception 'intake_disabled'; end if; insert into testimony_rate_limits(ip_hash,window_start,attempts) values(p_ip_hash,now(),1) on conflict(ip_hash) do update set window_start=case when testimony_rate_limits.window_start<now()-interval '1 hour' then now() else testimony_rate_limits.window_start end,attempts=case when testimony_rate_limits.window_start<now()-interval '1 hour' then 1 else testimony_rate_limits.attempts+1 end returning * into v_limit; if v_limit.attempts>3 then raise exception 'rate_limited'; end if; insert into testimonies(full_name,email,language,country,parish,event_date,healing_type,testimony_text,contact_permission,consent_publish,status) values(p_payload->>'full_name',nullif(p_payload->>'email',''),coalesce(nullif(p_payload->>'language',''),'en'),nullif(p_payload->>'country',''),nullif(p_payload->>'parish',''),nullif(p_payload->>'event_date','')::date,nullif(p_payload->>'healing_type',''),p_payload->>'testimony_text',coalesce((p_payload->>'contact_permission')::boolean,false),true,'pending') returning id into v_id; return v_id; end $$;
revoke all on function public.accept_testimony(text,jsonb) from public,anon,authenticated;
